static bool FP9050Leaf(const char* what);
//  COM2: the 910 flow uses the RTC vision members of golden TCOM2 (rs232.h) that TCOM2Shim does not have.  Superset copied
//  from atester.cpp W7T1_TCOM2Ext: the three Index Z torque members FORWARD to the real COM2 (rs232.cpp, R28TORQ -- the
//  12000 / 12200 limit writes and the 12110 reader reach the drive / the E-038 bridge), the RTC members are offline-inert
//  and bCCDDummyRum is true (as TCOM2Shim), so every `REAL_TIME_CCD && !COM2->bCCDDummyRum` branch stays unreachable.
enum { ST01C_rtLightOn=0, ST01C_rtRelease, ST01C_rtInspEnd, ST01C_rtOPENVERIFYOK, ST01C_rtOPENVERIFYNG, ST01C_rtALLPASSOK,
       ST01C_rtALLPASSNG, ST01C_rtSiteMap, ST01C_rtFullTOK, ST01C_rtFullTNG, ST01C_RT_N };
struct ST01C_TCOM2Ext {
    bool bCCDDummyRum;                                         // golden rs232.h:157 -- true (== TCOM2Shim)
    bool bRealTimeCom_ReceiveOK[ST01C_RT_N];                   // golden rs232.h -- all false
    int  rtLightOn, rtRelease, rtInspEnd, rtOPENVERIFYOK, rtOPENVERIFYNG, rtALLPASSOK, rtALLPASSNG, rtSiteMap, rtFullTOK, rtFullTNG;
    void DoReleaseAndInspEnd(){}                               // golden rs232.h:160 -- offline no-op (== TCOM2Shim)
    int  iWriteAndCheckMotorTorque(int iArm, int iPre){ return COM2->iWriteAndCheckMotorTorque(iArm, iPre); }   // real (rs232.cpp)
    int  GetReadTorueTask(){ return COM2->GetReadTorueTask(); }                                               // real
    void InitReadTorueTask(){ COM2->InitReadTorueTask(); }                                                     // real
    void SendCommToVision(int, bool){}                         // golden rs232.h -- offline no-op (unreachable: bCCDDummyRum)
    bool OpenRTCComPortAgain(){ return false; }                // golden rs232.h -- offline: no re-open (unreachable)
    ST01C_TCOM2Ext():bCCDDummyRum(true),rtLightOn(ST01C_rtLightOn),rtRelease(ST01C_rtRelease),rtInspEnd(ST01C_rtInspEnd),
                     rtOPENVERIFYOK(ST01C_rtOPENVERIFYOK),rtOPENVERIFYNG(ST01C_rtOPENVERIFYNG),rtALLPASSOK(ST01C_rtALLPASSOK),
                     rtALLPASSNG(ST01C_rtALLPASSNG),rtSiteMap(ST01C_rtSiteMap),rtFullTOK(ST01C_rtFullTOK),rtFullTNG(ST01C_rtFullTNG)
    { for(int i=0;i<ST01C_RT_N;i++) bRealTimeCom_ReceiveOK[i]=false; }
};
static ST01C_TCOM2Ext ST01C_com2_ext;
//  CCDInterfaceForm: TCCDInterfaceFormShim has only bAtestScanCCDProgram / CCDTimerOnOff / CCDRunExec (atester_shims.h);
//  those three FORWARD to it at use time.  The identification members the CCD branch (910 cases 2-7, only with
//  IniConfig.bEnableCCDUSETCPIP && bC02InstallCCD) needs are not translated: the branch's only entry (910 :2137) is a
//  leaf stop, and each untranslated call is a leaf stop too; their data members hold golden's "nothing yet" values.
struct ST01C_TCCDExt {
    struct ScanFlag { operator bool() const { return ::CCDInterfaceForm->bAtestScanCCDProgram; } } bAtestScanCCDProgram;
    void CCDTimerOnOff(bool b){ ::CCDInterfaceForm->CCDTimerOnOff(b); }
    bool CCDRunExec(){ return ::CCDInterfaceForm->CCDRunExec(); }
    void CloseCCDForm(){ FP9050Leaf("CCDInterfaceForm->CloseCCDForm"); }
    void CCDIdentificationOpen(){ FP9050Leaf("CCDInterfaceForm->CCDIdentificationOpen"); }
    void CCDIdentification(){ FP9050Leaf("CCDInterfaceForm->CCDIdentification"); }
    void RetrunUpStep(){ FP9050Leaf("CCDInterfaceForm->RetrunUpStep"); }
    bool bCCDProgramExistence, bIdentificationFinish;
    int  iIdentificationStatus;
    ST01C_TCCDExt():bCCDProgramExistence(false),bIdentificationFinish(false),iIdentificationStatus(0){}
};
static ST01C_TCCDExt ST01C_ccd_ext;
#ifdef COM2
#undef COM2
#endif
#define COM2 (&ST01C_com2_ext)
#define CCDInterfaceForm (&ST01C_ccd_ext)
