        case 500:
            #ifdef RecordMoveTime   //KaiHuang 20200625 : For 時序表,記錄各模組移動時間
                IndexZ_StartTime=GetTickCount();
                IndexZ_ReadTime=true;
                SaveMoveTime("Index Shuttle Pick To Z Safe - Start", " ");
            #endif

