//                if(bHPCleanout && Temperature.bPreheatOnHP==true && HOTPLATE_INSTALLATION==1)     //wei 20160624 Hotplate clean out   //Isaac 20190201 : 隔開有無hotplate   //Isaac 20191106 : 判斷是否跑加熱盤
//                {
