//  F1 in class terms (motor-control skill, motor-classes.md): with INDEX_MOTION_CARD==0 golden builds the Index axes as
//  TMyGALILMotor (cinitial.cpp InitialMotorParameter) and drives them only through TMyMotor's Galil API (Gali_MotMove /
//  Gali_ReadPos ...): that API is what reaches a DMC card, the Galil route (HT9050: PCIE-1203, Motor/GaliRoute.h) or golden's no-card
//  simulation, and it keeps the Galil sign convention (Position = -flow).  910's plain MOT[MTestZ1].ReadPos() / MotorMove go to
//  HTMotor::ReadPos / MoveToPos of TMyGALILMotor, which need a DMC card (bGali_CardInstall): 0 / no motion otherwise.
//  Index axes on another HTMotor class (INDEX_MOTION_CARD!=0): 910's ReadPos / MotorMove, unchanged.
int W906_FP9050Z1Pos()
{
    if(FP9050IndexOnGalilApi())
        return (int)MOT[MTestZ1].Gali_ReadPos();
    return MOT[MTestZ1].ReadPos();
}

//  P7 (Steven 1004 07:5x 「io 馬達的裝置有異常error的時候，機台就不可以動」): E-042's decision W906_IndexZDriveFault
//  (ALM / ERROR_STOP / servo off / 3 invalid samples / poll frozen 2 s / route-latched failure / no health hook), the same
//  "ST" first as E-042's W906_IndexZDriveFaultStop, with a message that names the production Index flow (E-042's says
//  "Auto Height stopped").  true -> the caller takes its exit in the same tick.
static bool g_fpP7Shown = false;
//  P7 class-level part: golden's own Index alarm rule (ScanIndexMotorCanMove, myGALILmotor.cpp: Led[iAlarmLed] && Enable &&
//  PServoAlarmOn) on the motor object's own scan -- Gali_ScanAlarmStatus ("TI") for Galil-API Index axes, TMyMotor::ScanMotorStatus
//  (alarm + servo-on lamp) for any other HTMotor class.  Works for a DMC card, the Galil route, EtherCAT or MotionNet axes alike.
static bool FP9050ClassFault(AnsiString* why)
{
    TMyMotor& z = MOT[MTestZ1];
    if(z.Motor==NULL || z.Motor->Enable==false) return false;          // no axis object / Mot_Table Enable 0: golden simulates it
    if(FP9050IndexOnGalilApi()) z.Gali_ScanAlarmStatus(); else z.ScanMotorStatus();
    if((z.Led[iAlarmLed] || z.Led[iServoalarmLed]) && z.Motor->PServoAlarmOn)
    {
        if(why) *why = z.Alias + " alarm (motor object Led[iAlarmLed] / Led[iServoalarmLed])";
        return true;
    }
    if(!FP9050IndexOnGalilApi() && z.Led[iServoOn]==false)
    {
        if(why) *why = z.Alias + " servo is OFF (motor object Led[iServoOn])";
        return true;
    }
    return false;
}
bool W906_FP9050DriveFaultStop(const char* where)
{
    AnsiString why;
    if(!FP9050ProtectLive()) return false;
    const bool fault = FP9050ClassFault(&why) || W906_IndexZDriveFault(&why);   // class level first; then E-042's 1203 health (reused as is)
    if(!fault) { g_fpP7Shown = false; return false; }
    MOT[MTestZ1].Gali_Command("ST", "W906_FP9050DriveFaultStop");      // golden's own stop string; never gated
    if(!g_fpP7Shown)
    {
        g_fpP7Shown = true;
        std::printf("[fp9050] P7 %s: Index Z1 drive error -> ST + exit: %s\n", where ? where : "", why.c_str());
        std::fflush(stdout);
        ShowMyMessage("Index Z1 drive error -- Index (FinePitch) stopped: " + why,
                      "Index Z1 驅動器異常 -- Index (FinePitch) 已停止: " + why, where ? where : "W906_FP9050DriveFaultStop");
    }
    return true;
}

//  W-44 (Steven 1005 23:1x, relayed by ST01-M / ST01-E 23:2x): 「Out shuttle 可能在執行5s的動作，所以應該是有個安全的x座標，在安全位置之外,
//  index就可以下壓到socket」(「5s是 ccd的五面檢查」 = the CCD five-side inspection) -- Index Z1 may press to the SOCKET while each shuttle's
//  X is OUTSIDE the index's safe zone; NOT "both shuttles at origin" (the 1004 wording, E-042's W906_IndexZShuttlesAtHome, no longer
//  used here). The decision is Frank's guard (FR-NB2 (2), RULINGS_20261005 #19); it does not exist yet, so this file only CALLS it
//  through W906_Ht9050ShuttlesClearOfIndexHook. Hook missing in a SHIP build = NOT clear (fail-safe: refuse / stop).
bool (*W906_Ht9050ShuttlesClearOfIndexHook)(AnsiString* why) = 0;
bool W906_FP9050ShuttlesClearOfIndex(AnsiString* why)
{
    if(why) *why = "";
    if(!FP9050ProtectLive()) return true;                              // SOFT_SIMULTE: 910, no check
    if(W906_Ht9050ShuttlesClearOfIndexHook == 0)
    {
        if(why) *why = "W-44: no shuttle safe-zone guard installed (Frank FR-NB2 (2) not in this build) -- Index Z1 may not press (fail-safe)";
        return false;
    }
    return W906_Ht9050ShuttlesClearOfIndexHook(why);
}

